//! Code validation and formatting.

use proc_macro2::TokenStream;

use crate::errors::GeneratorError;

/// Header comment prepended to every `.rs` file this generator writes.
///
/// Doubles as an ownership marker: stale-file cleanup only removes files whose
/// first line begins with this text, so hand-written files are never deleted.
pub const GENERATED_FILE_HEADER: &str =
    "// This code was automatically generated by schematic-gen. Do not edit manually.";

/// Validates generated code using syn.
///
/// Parses the token stream as a complete Rust file. This checks grammar/syntax
/// only: it confirms the tokens form a parseable file, but does not type-check,
/// resolve names, or guarantee the code compiles.
///
/// ## Arguments
///
/// * `tokens` - The generated code to validate
///
/// ## Returns
///
/// The parsed `syn::File` on success, or an error if the code is invalid.
///
/// ## Errors
///
/// Returns `GeneratorError::CodeGenError` if the code fails to parse.
pub fn validate_code(tokens: &TokenStream) -> Result<syn::File, GeneratorError> {
    syn::parse2(tokens.clone())
        .map_err(|e| GeneratorError::CodeGenError(format!("Generated code is invalid: {}", e)))
}

/// Formats generated code using prettyplease.
///
/// Converts a parsed syn::File back to a nicely formatted string,
/// prepending an auto-generated notice as a regular comment.
///
/// ## Arguments
///
/// * `file` - The parsed Rust file to format
///
/// ## Returns
///
/// A formatted string representation of the code with auto-generated notice.
pub fn format_code(file: &syn::File) -> String {
    let formatted = prettyplease::unparse(file);
    format!("{GENERATED_FILE_HEADER}\n\n{formatted}")
}
